  "curl -X POST {value0}/automation/results -H \"x-api-key: <middleware inbound key>\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{ \"analyzerCode\": \"HEM01\", \"sampleNo\": \"S2609300001\",\n        \"results\": [ { \"code\": \"HGB\", \"value\": 13.2 }, { \"code\": \"WBC\", \"value\": 7.1 } ] }'\n\ncurl -X POST {value1}/automation/results -H \"x-api-key: <key>\" -H \"Content-Type: application/hl7-v2\" \\\n  --data-binary $'MSH|^~\\\\&|CHEM01|LAB|LIS|LAB|20260930120000||ORU^R01|1|P|2.5\\rOBR|1||S2609300002\\rOBX|1|NM|CREA||0.9|mg/dL'": "curl -X POST {value0}/automation/results -H \"x-api-key: <middleware inbound key>\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{ \"analyzerCode\": \"HEM01\", \"sampleNo\": \"S2609300001\",\n        \"results\": [ { \"code\": \"HGB\", \"value\": 13.2 }, { \"code\": \"WBC\", \"value\": 7.1 } ] }'\n\ncurl -X POST {value1}/automation/results -H \"x-api-key: <key>\" -H \"Content-Type: application/hl7-v2\" \\\n  --data-binary $'MSH|^~\\\\&|CHEM01|LAB|LIS|LAB|20260930120000||ORU^R01|1|P|2.5\\rOBR|1||S2609300002\\rOBX|1|NM|CREA||0.9|mg/dL'",
  "curl -X POST {value0}/integration/orders \\\n  -H \"x-api-key: <external system key>\" -H \"Content-Type: application/json\" \\\n  -d '{\n    \"externalOrderNo\": \"HIS-1001\",\n    \"priority\": \"ROUTINE\",\n    \"patient\": { \"externalPatientId\": \"P77\", \"firstName\": \"Ali\", \"lastName\": \"Khan\",\n                 \"dob\": \"1970-01-01\", \"gender\": \"M\" },\n    \"doctor\":  { \"code\": \"DR1\", \"name\": \"Dr House\" },\n    \"tests\":   [\"TSH\", \"GLUF\"],\n    \"clinicalNotes\": \"Fatigue\"\n  }'": "curl -X POST {value0}/integration/orders \\\n  -H \"x-api-key: <external system key>\" -H \"Content-Type: application/json\" \\\n  -d '{\n    \"externalOrderNo\": \"HIS-1001\",\n    \"priority\": \"ROUTINE\",\n    \"patient\": { \"externalPatientId\": \"P77\", \"firstName\": \"Ali\", \"lastName\": \"Khan\",\n                 \"dob\": \"1970-01-01\", \"gender\": \"M\" },\n    \"doctor\":  { \"code\": \"DR1\", \"name\": \"Dr House\" },\n    \"tests\":   [\"TSH\", \"GLUF\"],\n    \"clinicalNotes\": \"Fatigue\"\n  }'",
  "curl -X POST {value0}/outsource/results -H \"x-api-key: <reference lab key>\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{ \"sampleNo\": \"S2609300002\", \"testCode\": \"VITD\",\n        \"results\": [ { \"code\": \"VITD\", \"value\": \"18\" } ], \"reportedBy\": \"RefLab\" }'": "curl -X POST {value0}/outsource/results -H \"x-api-key: <reference lab key>\" \\\n  -H \"Content-Type: application/json\" \\\n  -d '{ \"sampleNo\": \"S2609300002\", \"testCode\": \"VITD\",\n        \"results\": [ { \"code\": \"VITD\", \"value\": \"18\" } ], \"reportedBy\": \"RefLab\" }'",
  "curl {value0}/automation/middleware/orders -H \"x-api-key: <middleware inbound key>\"\n# returns pending order messages and marks them SENT": "curl {value0}/automation/middleware/orders -H \"x-api-key: <middleware inbound key>\"\n# लंबित ऑर्डर संदेश लौटाता है और उन्हें SENT के रूप में चिह्नित करता है",
